import sys

import numpy as np
import wgpu

SHADER = """
struct Params { width: u32, height: u32 };

@group(0) @binding(0) var<storage, read> src: array<u32>;
@group(0) @binding(1) var<storage, read_write> dst: array<u32>;
@group(0) @binding(2) var<uniform> params: Params;

@compute @workgroup_size(16, 16)
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {
    let x = gid.x;
    let y = gid.y;
    let w = params.width;
    let h = params.height;
    if (x >= w || y >= h) {
        return;
    }
    let xl = select(x - 1u, 0u, x == 0u);
    let xr = select(x + 1u, w - 1u, x + 1u >= w);
    let yu = select(y - 1u, 0u, y == 0u);
    let yd = select(y + 1u, h - 1u, y + 1u >= h);
    let s = 4u * src[y * w + x] + src[y * w + xl] + src[y * w + xr]
          + src[yu * w + x] + src[yd * w + x];
    dst[y * w + x] = s / 8u;
}
"""


def diffuse(grid, steps):
    height, width = grid.shape
    if steps == 0:
        return grid
    device = wgpu.utils.get_default_device()
    usage = wgpu.BufferUsage.STORAGE | wgpu.BufferUsage.COPY_SRC | wgpu.BufferUsage.COPY_DST
    data = np.ascontiguousarray(grid, dtype=np.uint32)
    bufs = [device.create_buffer_with_data(data=data, usage=usage),
            device.create_buffer(size=data.nbytes, usage=usage)]
    params = device.create_buffer_with_data(
        data=np.array([width, height], dtype=np.uint32),
        usage=wgpu.BufferUsage.UNIFORM)
    module = device.create_shader_module(code=SHADER)
    pipeline = device.create_compute_pipeline(
        layout="auto", compute={"module": module, "entry_point": "main"})
    layout = pipeline.get_bind_group_layout(0)
    groups = []
    for a, b in ((0, 1), (1, 0)):
        groups.append(device.create_bind_group(layout=layout, entries=[
            {"binding": 0, "resource": {"buffer": bufs[a], "offset": 0, "size": data.nbytes}},
            {"binding": 1, "resource": {"buffer": bufs[b], "offset": 0, "size": data.nbytes}},
            {"binding": 2, "resource": {"buffer": params, "offset": 0, "size": 8}},
        ]))
    gx, gy = (width + 15) // 16, (height + 15) // 16
    encoder = device.create_command_encoder()
    cpass = encoder.begin_compute_pass()
    cpass.set_pipeline(pipeline)
    for i in range(steps):
        cpass.set_bind_group(0, groups[i % 2])
        cpass.dispatch_workgroups(gx, gy, 1)
    cpass.end()
    device.queue.submit([encoder.finish()])
    out = device.queue.read_buffer(bufs[steps % 2])
    return np.frombuffer(out, dtype=np.uint32).reshape(height, width)


def main():
    with open(sys.argv[1]) as f:
        tokens = f.read().split()
    width, height, steps = int(tokens[0]), int(tokens[1]), int(tokens[2])
    cells = np.array(tokens[3:3 + width * height], dtype=np.int64)
    grid = cells.reshape(height, width)
    result = diffuse(grid, steps)
    lines = [" ".join(map(str, row)) for row in result.tolist()]
    total = int(result.astype(np.int64).sum())
    sys.stdout.write("\n".join(lines) + f"\nSUM {total}\n")


if __name__ == "__main__":
    main()
