import subprocess, sys, random
import numpy as np


def ref(g, steps):
    g = np.array(g, dtype=np.int64)
    for _ in range(steps):
        p = np.pad(g, 1, mode="edge")
        g = (4 * g + p[1:-1, :-2] + p[1:-1, 2:] + p[:-2, 1:-1] + p[2:, 1:-1]) // 8
    return g


def run(w, h, steps, tmp_path, seed=0):
    rng = random.Random(seed)
    g = [[rng.randint(0, 1000000) for _ in range(w)] for _ in range(h)]
    p = tmp_path / "in.txt"
    p.write_text(f"{w} {h} {steps}\n" + "\n".join(" ".join(map(str, r)) for r in g) + "\n")
    out = subprocess.run([sys.executable, "main.py", str(p)], capture_output=True, text=True, check=True).stdout
    exp = ref(g, steps)
    lines = out.strip("\n").split("\n")
    assert lines[-1] == f"SUM {int(exp.sum())}"
    assert lines[:-1] == [" ".join(map(str, r)) for r in exp.tolist()]


def test_small(tmp_path):
    run(5, 3, 7, tmp_path)


def test_one_cell(tmp_path):
    run(1, 1, 10, tmp_path)


def test_zero_steps(tmp_path):
    run(4, 4, 0, tmp_path)


def test_odd_even_steps(tmp_path):
    run(17, 33, 1, tmp_path)
    run(17, 33, 2, tmp_path)


def test_large(tmp_path):
    run(512, 512, 50, tmp_path)
